class Solution {
  private Boolean[] memo;

  public boolean canIWin(int maxChoosableInteger, int desiredTotal) {
    if (desiredTotal <= 0) return true;
    if (maxChoosableInteger * (maxChoosableInteger + 1) / 2 < desiredTotal) return false;
    memo = new Boolean[1 << maxChoosableInteger];
    return wins(maxChoosableInteger, desiredTotal, 0);
  }

  // true if the player to move wins with `remaining` still needed and `used` numbers taken
  private boolean wins(int max, int remaining, int used) {
    if (memo[used] != null) return memo[used];
    for (int i = 1; i <= max; i++) {
      int bit = 1 << (i - 1);
      if ((used & bit) != 0) continue;
      if (i >= remaining || !wins(max, remaining - i, used | bit)) return memo[used] = true;
    }
    return memo[used] = false;
  }
}
